            "notes": "START\n00 5\n30 4\n02 6\n00 0\nNODE\nSTRUCTURE ROWC OLUMN VALUE Address ofnext node\n02 3\nNULL\n04 41\n25 13\n332 26\n\n## 3.3 Algorithm to Represent the Sparse Matrix\n\nSTEP-1    Input the array of mXn elements.\nSTEP-2    [COUNT THE NUMBER OF NON ZERO ELEMENTS]\n                             REPEAT For I = 1 to m\n                                 REPEAT For j = 1 to n\n                                          If arr[i][j] !=0 THEN:\n                                              Count := count+ 1\n    [END OF IF]\n       [END OF LOOP]\n   [END OF LOOP]\nSTEP-3  SP[0][0] := m\n                              SP[0][1]:=n\n                              SP[0][2]  :=  COUNT\nSTEP-4  K:=1\n                              REPEAT For I = 0 to m\n               REPEAT For j = 0 to n\n                             If  arr[i][j] !=0 THEN:\n                                    Sp[k][0] := I\n                                      Sp[k][1]:=j\n                                Sp[k][2] := arr[i][j]\n                                  K:=k+1\n          [END OF IF]\n      [END OF LOOP]\n  [END OF LOOP\nSTEP-5  REPEAT For I = 1 to k+1\n                                    REPEAT For j = 1 to 3\n                                 Print sp[i][j]\n       [END OF LOOP]\n   [END OF LOOP\nSTEP-6  EXIT\n\n## 3.4 Programs Related to Sparse Matrix\n\nProgram for Array Representation of Sparse Matrix\n\n```cpp\n#include<iostream>\n#include<iomanip>\nusing namespace std;\n//driver program\nint main()\n {\n   int arr[10][10],i,j,row,col,count=0,k=0,sp[15][3];\n   //ask user about the numbe o3f ows and columns sparse matx\n   cout<<\"\\nENTER HOW MANY ROWS AND COLUMNS\";\n   //read row and col\n   cin>>row>>col;\n   //loop to read the normal matrix\n     for(i=0;i<row;i++)\n for(j=0;j<col;j++)\n   {\n     cout<<endl<<\"Enter a number\";\n     cin>>arr[i][j];\n   }\n```\n\n   //loop to print the normal matrix that read from user\n   cout<<\"\\nTHE ENTERED ARRAY ELEMENTS ARE\\n\";\n       for(i=0;i<row;i++)\n       {\n   for(j=0;j<col;j++)\n     cout<<setw(4)<<arr[i][j];\n     cout<<endl;\n       }\n//loop to count the number of non zero elements in the matrix\n     for(i=0;i<row;i++)\n       for(j=0;j<col;j++)\n     if(arr[i][j]!=0)//condition for non zero elements\n   count++; //increase the count\n    \n    //set the first row of sparse matrix\nsp[0][0]=row;  \n    sp[0][1]=col;\n    sp[0][2]=count;\n     k=1;//k points to second row of sparse matrix\n     //loop to fill theother rows of sparse matrix\n       for(i=0;i<row;i++)\n   for(j=0;j<col;j++)\n       {\n  if(arr[i][j]!=0)\n     {\n        sp[k][0]=i;\n        sp[k][1]=j;\n        sp[k][2]=arr[i][j];\n        k++;\n      }\n   }\n   //print the sparse matrix\n     cout<<\"\\nTHE SPRASE MATRIX IS\\n\";\n       for(i=0;i<=count;i++)\n  {\n  for(j=0;j<3;j++)\n    cout<<\"  \"<<sp[i][j];\n  cout<<endl;\n }\n      }\nOUTPUT\n\nTranspose of a Sparse Matrix\n\n```cpp\n#include<iostream>\n#include<iomanip>\nusing namespace std;\nint  main()\n {\n    int arr[10][10],i,j,row,col,count=0,k=0,sp[15]\n[3],tran[10][3];\n  \n      //ask user about the numbe o3f ows and columns sparse matx\n   cout<<\"\\nENTER HOW MANY ROWS AND COLUMNS\";\n   //read row and col\n   cin>>row>>col;\n   //loop to read the normal matrix\n     for(i=0;i<row;i++)\n for(j=0;j<col;j++)\n   {\n     cout<<endl<<\"Enter a number\";\n     cin>>arr[i][j];\n   }\n```\n\n   //loop to print the normal matrix that read from user\n cout<<\"\\nTHE ENTERED ARRAY ELEMENTS ARE\\n\";\n       for(i=0;i<row;i++)\n       {\n for(j=0;j<col;j++)\n     cout<<setw(4)<<arr[i][j];\n     cout<<endl;\n       }\n//loop to count the number of non zero elements in the matrix\n     for(i=0;i<row;i++)\n       for(j=0;j<col;j++)\n     if(arr[i][j]!=0)//condition for non zero elements\n   count++; //increase the count\n    \n    //set the first row of sparse matrix\nsp[0][0]=row;  \n    sp[0][1]=col;\n    sp[0][2]=count;\n     k=1;//k points to second row of sparse matrix\n     //loop to fill theother rows of sparse matrix\n       for(i=0;i<row;i++)\n   for(j=0;j<col;j++)\n       {\n  if(arr[i][j]!=0)\n     {\n        sp[k][0]=i;\n        sp[k][1]=j;\n        sp[k][2]=arr[i][j];\n        k++;\n      }\n   }\n   //print the sparse matrix\n     cout<<\"\\nTHE SPRASE MATRIX IS\\n\";\n       for(i=0;i<=count;i++)\n   {\n  for(j=0;j<3;j++)\n    cout<<\"  \"<<sp[i][j];\n  cout<<endl;\n  }\n       /*TRANSPOSE*/\n      tran[0][0]=col;\n      tran[0][1]=row;\n      tran[0][2]=count;\n k=1;\n   for(i=0;i<col;i++)\n     for(j=1;j<=count;j++)\n       {\n     if(sp[j][1]==i)\n   {\n    tran[k][0]=sp[j][1];\n    tran[k][1]=sp[j][0];\n    tran[k][2]=sp[j][2];\n    k++;\n    }\n   }\n    cout<<\"\\nTRANSPOSE OF THE SPRASE MATRIX \nIS\\n\";\n    for(i=0;i<=count;i++)\n    {\n      for(j=0;j<3;j++)\n       cout<<setw(5)<<tran[i][j];\n       cout<<endl;\n     }\n      }\n",
